from ui_incremental import *
record(P+'ViewModels/ReportsViewModel.cs','Read-only multi-endpoint management report compositor.',[
('ReportsViewModel(', 'Initial date is Cairo; period defaults today without triggering generated setter. Specific-day bridge uses UTC offset only as calendar carrier.'),
('OnSelectedPeriodChanged(', 'Notifies range/day picker and launches reload unless ShowDay suppresses duplicate. Rapid changes coalesce via reload flag rather than cancelling network reads.'),
('ShowDay(', 'Switches to day with try/finally suppression, updates date offset and label then starts read. PreviousDay/NextDay both delegate here.'),
('ResolveRange(', 'Inclusive ranges cover today/yesterday/7/30/month or selected date using shared BusinessClock; no money calculation.'),
('OnFoodCostChanged(', 'Recomputes incomplete count and current recipe/current ingredient cost disclosure. Unknown line costs stay distinct from zero.'),
('BuildProductHours(', 'Sorts active hours, groups by product name, sums quantity, picks earliest tied peak and caps 15 rows. Dictionary requires one row per product/hour; corroborated ReportingQueryService groups exactly that key, rejecting duplicate-row candidate for current backend. Display dots denote zero, not absent cost.'),
('LoadAsync(', 'Sequentially loads sales, expense, top, hourly, categories, delivery, tax, refunds, food cost, actions. Failure keeps partial old/new fields but HasData requires no error, hiding successful data region. finally executes requested reload while retaining loading cover. No stale-range early discard, but cover remains through queued reload. Session user asserted nonnull; no cancellation. No financial writes.'),
('BusinessDateOffset', 'Setter calls ShowDay only for changed calendar day. BusinessDateLabel notified by generated hook; current range not updated by direct BusinessDate setter outside bridge.')
], 'NOT_EXECUTED. Test rapid date changes, every intermediate endpoint failure, tied peaks and empty/missing costs. Product/hour duplicate exception is not established with actual backend grouping.', 'Retain explicit unknown-cost basis. Consider cancellation/session generation and atomic report snapshot to simplify failure handling.')
record(P+'ViewModels/OwnerDashboardViewModel.cs','Owner KPI, attention and trend presentation from one server DTO.',[
('OwnerDashboardViewModel(', 'SelectedPeriod setter immediately starts LoadAsync; synchronous prefix checks reports_view and session. Navigation callback only routes to existing shell.'),
('ResolveRange(', 'Shared Cairo clock defines inclusive periods consistently with reports.'),
('LoadAsync(', 'Coalesces concurrent reloads, compares captured range after await and discards mismatched DTO. Sets Data null/error on failure; finally releases spinner. No cancellation/session identity generation; same-range identity change not checked.'),
('Open(', 'Attention item null/nav null is ignored; downstream shell must permission-gate target.'),
('RebuildVisibleAttention(', 'First three or all preserve insertion order; toggle labels/count notified. Contrary comment severity order is not sorted after later bad items are appended; critical backup/cost/printing warnings may remain below three expanded rows.'),
('ToggleAttention(', 'Flips flag, generated hook rebuilds rows. Reset on fresh Data limits persistent expansion.'),
('OnDataChanged(', 'Rebuilds all collections, limits low-stock to six, retains all print routes and refreshes derived displays. Clearing Data removes previous collections.'),
('RebuildMetrics(', 'Formats server net/collected/driver/expense/cost values without recomputing business totals. Net and collected share net trend points; their headline deltas use respective server ChangeDto. Unknown food percent displays unknown.'),
('Card(', 'No comparison percent produces none direction; nonzero delta without ratio overrides caption. Required metrics hold independent strings/point collections.'),
('DescribeChange(', 'Null percent becomes no comparison; negative uses absolute magnitude with downward glyph. Money uses integer piastre formatter.'),
('RebuildAttention(', 'Builds backup, discrepancy, driver, electronic, stock, exceptions, close, print, cost, payable, attendance, old-day and cost-change warnings. Later critical rows appended after earlier info; thresholds24h/72h backup and10minute print are UI policy. Missing success does not prove physical route failure.'),
('RebuildSplit(', 'Computes channel display shares only for positive total. Zero total uses em dash, not zero percent. Server financial totals remain authoritative.'),
('UnknownCostLabel', 'Distinguishes no known cost from incomplete cost; lists up to six missing names.'),
('BackupLabel', 'Shows local-machine timestamp, reported server age, and Valid/Invalid vocabulary correctly. Null age falls back zero, which could misstate freshness if backend omits age despite timestamp.')
], 'NOT_EXECUTED. Tests stale period result discard, permission absence, no data, null ratios, all late critical alerts with collapsed list, unknown cost and valid/invalid backup.', 'Order attention explicitly by severity if comment and operator priority intended. Label collected sparkline with its actual series or provide matching collected trend.')
record(P+'Views/MenuEditorView.xaml','RTL overlay editing menu, variants, tax and offers.',[
('SetKindCommand', 'Four equal segments bind kind commands and parameterized converter colors. Selected white/brand pairing differs from unselected neutral/muted. Permission-specific controls reflected through CanManageKind and CanEdit.'),
('SelectRowCommand', 'Catalogue buttons bind root VM explicitly; they have no explicit IsImageBusy disabling. VM CanBrowse does not exclude image busy, corroborating async A image completion versus B selection candidate.'),
('HasEditor', 'Empty prompt is duplicated: decorative Border and later TextBlock share same inverse flag and grid cell, a source-observed overlap risk requiring native render. Fixed360px list plus editor can compress at narrow windows.'),
('CanEditImage', 'Only choose/delete image buttons use CanEditImage; other fields/selection/save use CanEdit. Spinner shows image busy but does not overlay form. ProductImageUri uses URL cache converter; hint states512KB formats.'),
('Variants', 'Root explicit bindings scope nested item commands and recipe choices correctly. Fixed120/170px columns plus name/delete create horizontal width pressure at text scale.'),
('PriceProducts', 'Days and products use two-way selection with write gating. Max260px offers list scrolls inside larger editor scroll; focus/keyboard testing required.'),
('SaveLabel', 'Save caption can express retry; CanEdit remains actual enablement. Action errors/success wrap at footer. Overlay is Grid not ContentDialog: no modal focus trap or Escape dismissal in this file.')
], 'NOT_EXECUTED. Verify selection while picker/upload pending with fake delayed image API, narrow viewport/text scaling, nested commands, focus containment and recovery after restart.', 'Bind all editor navigation to coherent image/write busy state and capture selection generation before applying image result. Remove duplicate empty prompt after visual verification; no source changes implemented.')
record(P+'Views/CashierOperationsModalsView.xaml','Cashier safe drop, drawer cash movements, drawer log, balance and order lookup overlays.',[
('IsSafeDropOpen', 'Amount/reason/manager fields two-way immediate, disabled by shared CanEditOperation; manager PIN PasswordBox appears only approval required. Submit relies command gating, footer not independent busy field.'),
('IsCashMovementOpen', 'Cash in/out shares title and retained VM fields; reason and amount explicit automation IDs. Overlay itself no focus trap.'),
('IsCashDrawerOpen', 'Text explicitly says records a drawer request rather than confirming physical drawer opened. No direct device call in XAML.'),
('IsCashCountOpen', 'Read-only server ledger balance hides while loading, then displays amount even if error also present; check VM null/reset so previous balance cannot be mistaken for current. No reconciliation write here.'),
('IsOrderLookupOpen', 'Number/search binds VM; summary gives order status, piastres, actual split payment, table and pickup time. Items cap220 inside outer ScrollViewer, potential clipping with many lines.'),
('LookupHasPendingPayment', 'Pending review/refund/reprint depend separate flags and commands; reprint is physical request pathway, not print preview. No printer-free full receipt rendering present in this view.'),
('CloseAutomationId', 'Header close commands vary per overlay and must preserve unresolved operations in VM. Shared CanEditOperation freezes input but native keyboard accelerator isolation is not provided here.')
], 'NOT_EXECUTED. Test pending locks, command retries, null balance/error display, many-line lookup, screen reader names of placeholder-only fields and native modal focus.', 'Keep financial pending journal concerns UI001 distinct from markup. Add explicit accessible field names/focus containment and a separate receipt preview if desired later.')
record(P+'Converters/Converters.cs','Shared one-way WinUI display, visibility, label, brush and image converters.',[
('BoolToVisibleConverter', 'True alone visible; inverse treats null/false as visible. Null/empty string visibility and empty string inverse do not trim whitespace. All corresponding ConvertBack throw; bindings must remain one-way.'),
('NullablePiastresToDisplayConverter', 'Long formats piastres using CashInput; absent/wrong numeric type remains unvalued, preserving missing cost. MoneyOrUnknown differs label only; PiastresToDisplay accepts long/int/null but wrong type returns0.00, potentially masking schema mismatch.'),
('TreasuryMovementTypeLabelConverter', 'Maps immutable snake_case ledger types to Arabic without rewriting IDs; unknown passes through. PaymentMethod lowercases; user/employee/stock labels use exact server vocabulary and unknown fallbacks.'),
('PrintRouteLabelConverter', 'All six routes including DeliveryOrder/DriverDispatch map. SignificantAction delegates by category; delivery assignment/reassignment/ready labels separate. Treasury null account explicitly outside system.'),
('MilliUnitsToDisplayConverter', 'Only long supported, no unit conversion ambiguity; positive amount accepts long>0 only. Count positive accepts int only. Strict DTO types should be tested.'),
('DeliveryStatusLabelConverter', 'PascalCase delivery statuses separate from case-normalized order statuses. Order type handles historical dine_in/dinein as pickup. General statuses map payroll/business day/backup Valid Invalid and audit severity.'),
('BoolToBrushConverter', 'Splits required parameter without validation and resolves concrete theme Brush; string/int variants expect three pieces. Bad XAML parameters throw; ThemeResources/theme refresh risk UI004. Label bool split likewise unguarded.'),
('ShiftDotBrushConverter', 'Static emerald/slate brushes independent of theme; require accompanying textual status for non-color access. Severity and delta resolve theme brushes; unknown severity defaults success, so unrecognized severity can appear green.'),
('PercentOrUnknownConverter', 'Double formatted invariant; no finite check so malformed NaN/infinity would print. Fraction clamps positive shares to150px max with4px minimum, zero/negative/NaN to0; presentation only.'),
('LocalTimestampConverter', 'Timestamp converts machine timezone; TimeOfDay also machine local with ar-EG culture. CairoBusinessDate extracts calendar DateTime directly without timezone conversion; correct only when input already business-date carrier, not arbitrary instant.'),
('FileNameConverter', 'Reduces nonempty path with Path.GetFileName; null empty. NullToBool excludes null/empty not whitespace. NullToText trims whitespace semantics by IsNullOrWhiteSpace.'),
('StringEqualsToVisibleConverter', 'Ordinal equality only; count>one expects ICollection. Empty/Nonempty collection depend on binding re-evaluation; ZeroCount explicitly binds Count int to avoid unchanged collection object bug.'),
('InverseBoolConverter', 'Both directions value is not true; malformed/null value becomes true. Binding bool contract should prevent unintended coercion.'),
('NavKeyToGlyphConverter', 'Known module keys map Segoe Fluent private-use glyphs; unknown generic fallback. Accessible textual navigation label still required.'),
('AttendanceStatusLabelConverter', 'Lowercase attendance vocabulary maps Arabic; unknown source value passed through. StatusToPillBrush uses substring matching and success tests first: hypothetical unpaid/inactive contain paid/active and look successful; no current emitted contract verified for those strings, so candidate only.'),
('ImageUriToSourceConverter', 'Process-static locked dictionary caches320px BitmapImage for every absolute URI, no eviction/error invalidation. Versioned URLs prevent stale photo reuse but repeated image versions accumulate until exit. Relative Uri.AbsoluteUri throws; caller currently expected absolute. NOT measured memory.'),
('ZeroCountToVisibleConverter', 'Only int0 visible; correctly bind Count property rather than collection to receive changes. Every ConvertBack unsupported except inverse bool, which is an intentional symmetric conversion.')
], 'NOT_EXECUTED. Table-driven tests should cover every vocabulary, wrong/null DTO type, parameter arity, theme switch, relative URI, cache version churn, current-zone versus Cairo date and Count mutation. No generic Convert heading used to claim every method individually mapped.', 'Keep strict schema types explicit, resource lookup dynamic per theme, bounded image cache and fail-safe neutral unknown status. No runtime visual contrast proof claimed.')
